def tramo_unico(texto: str) -> str:
    ultimo_indice = {}
    inicio = 0
    mejor_inicio = 0
    mejor_largo = 0

    for i, caracter in enumerate(texto):
        if caracter in ultimo_indice and ultimo_indice[caracter] >= inicio:
            inicio = ultimo_indice[caracter] + 1

        ultimo_indice[caracter] = i

        largo_actual = i - inicio + 1
        if largo_actual > mejor_largo:
            mejor_largo = largo_actual
            mejor_inicio = inicio

    return texto[mejor_inicio:mejor_inicio + mejor_largo]
