def tramo_unico(texto):
    if not texto:
        return ""

    ultimo_visto = {}
    inicio = 0
    mejor_inicio = 0
    mejor_largo = 0

    for i, caracter in enumerate(texto):
        if caracter in ultimo_visto and ultimo_visto[caracter] >= inicio:
            inicio = ultimo_visto[caracter] + 1

        ultimo_visto[caracter] = i
        largo_actual = i - inicio + 1

        # Solo actualizamos si es estrictamente más largo,
        # así en caso de empate conservamos el primero.
        if largo_actual > mejor_largo:
            mejor_largo = largo_actual
            mejor_inicio = inicio

    return texto[mejor_inicio:mejor_inicio + mejor_largo]
